(* spec 0RB0LD_0RC1RB_1LD1RC_0LA1LA *)
Definition r_AST_140_0000 : list (option Trans) := [t0RB;t0LD;t0RC;t1RB;t1LD;t1RC;t0LA;t1LA].
Lemma cv_AST_140_0000 : coversTr (row_to_tm r_AST_140_0000).
Proof. assert(Hhit:finite_instr_hit(row_to_tm r_AST_140_0000)(StB,S1)).
  { apply(finite_instr_conjugate source_AST_140_0000 _ perm_AST_140_0000 false (StB,S1)).
    - intros[] [];reflexivity.
    - intros[];first[exists StA;reflexivity|exists StB;reflexivity|
                    exists StC;reflexivity|exists StD;reflexivity].
    - apply ac_finite;reflexivity. }
  assert(Htotal:forall q s,exists tr,row_to_tm r_AST_140_0000 q s=Some tr)
    by(intros[] [];eexists;reflexivity).
  pose proof(finite_instr_recurrent _ _ Htotal Hhit)as Hrec.
  apply coversTr_nqh,neverqhtr_mirror.
  apply(ngram_check_neverqh_fuelmixtr_except_sound _ 3 0 3360 19
    skip_AST_140_0000 cert_AST_140_0000).
  - intros[[] []] H N;try discriminate.
    destruct(Hrec N)as(j&Hj&Hf). exists j;split;[exact Hj|apply mirror_fires;exact Hf].
  - vm_compute;reflexivity. Qed.

